      "role": "user_intent",
      "fact": "User asked about current payment and potential savings, but did not explicitly request or confirm interest in applying a loyalty discount."
    },
    {
      "source_id": "q15",
      "actor": "system",
      "role": "policy",
      "fact": "Loyalty discount is optional for agents to mention, and no confirmation is required for declining it."
